inline const SWS *GetSWS(const void *buf) {
  return ::flatbuffers::GetRoot<SWS>(buf);
}

inline const SWS *GetSizePrefixedSWS(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SWS>(buf);
}

inline const char *SWSIdentifier() {
  return "$SWS";
}

inline bool SWSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SWSIdentifier());
}

inline bool SizePrefixedSWSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SWSIdentifier(), true);
}

template <bool B = false>
inline bool VerifySWSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SWS>(SWSIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSWSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SWS>(SWSIdentifier());
}

inline void FinishSWSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SWS> root) {
  fbb.Finish(root, SWSIdentifier());
}

inline void FinishSizePrefixedSWSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SWS> root) {
  fbb.FinishSizePrefixed(root, SWSIdentifier());
}

